(()=>{"use strict";async function e(){try{const e=await chrome.runtime.sendMessage({action:"getQueueStats"});if(e.success&&e.stats){const t=e.stats;let n="已停止";t.isRunning&&(n=t.isPaused?"⏸️ 已暂停":"▶️ 运行中"),document.getElementById("queueStatus").textContent=n,document.getElementById("pendingCount").textContent=t.pending.toString(),document.getElementById("sentToday").textContent=t.repliesInLastDay.toString()}}catch(e){console.error("更新状态失败:",e)}}document.addEventListener("DOMContentLoaded",async()=>{await e(),document.getElementById("openReview")?.addEventListener("click",()=>{chrome.tabs.create({url:chrome.runtime.getURL("review.html")})}),document.getElementById("openOptions")?.addEventListener("click",()=>{chrome.runtime.openOptionsPage()}),document.getElementById("startQueue")?.addEventListener("click",async()=>{const t=await chrome.runtime.sendMessage({action:"startQueue"});t.success?await e():alert("启动失败: "+t.error)}),document.getElementById("pauseQueue")?.addEventListener("click",async()=>{(await chrome.runtime.sendMessage({action:"pauseQueue"})).success&&await e()}),document.getElementById("stopQueue")?.addEventListener("click",async()=>{(await chrome.runtime.sendMessage({action:"stopQueue"})).success&&await e()}),setInterval(e,5e3)})})();